'use strict';
(()=>{
 const D=window.GameData,K=window.CharacterData,R=window.ResultStory,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),sum=a=>a.reduce((n,x)=>n+x,0),num=n=>n==null?'미기록':n.toFixed(1);
 function analyze(report){
  const fights=(report.results||[]).map((r,i)=>{const config=r.practice?.config,start=config?.hp||null,previous=i?report.results[i-1].hp:null,deck=R.cards(r),delta=R.changes(R.baseline(report,i),deck);return {index:i,name:r.name,room:config?config.depth+1:null,start:start?sum(start):null,end:sum(r.hp),net:start?sum(r.hp)-sum(start):null,between:start&&previous?sum(start)-sum(previous):null,revived:start&&previous?start.filter((n,j)=>n>0&&previous[j]===0).length:null,received:r.stats.received?sum(r.stats.received):null,healed:r.stats.healed[0],firstKO:r.insights?.firstKO||null,changed:delta,usedNew:(delta||[]).filter(c=>c.after>c.before&&r.stats.cards[0][c.key]>0).map(c=>c.key),winner:r.winner};});
  const losses=fights.filter(r=>r.net!==null&&r.net<0).sort((a,b)=>a.net-b.net),failure=fights.find(r=>r.winner!==0),pressure=failure||losses[0]||null,changes=R.changes(report.initialDeck,report.finalDeck),end=fights.at(-1),boss=fights.find(r=>report.results[r.index].practice?.config.encounter.enemies.some(a=>a.boss));
  return {fights,pressure,boss,changes,end,recovered:fights.slice(1).every(r=>r.between!==null)?fights.reduce((n,r)=>n+Math.max(0,r.between||0),0):null,changesKnown:fights.every(r=>r.changed!==null),usedNew:[...new Set(fights.flatMap(r=>r.usedNew))]};
 }
 function panel(report){const a=analyze(report);if(!a.fights.length)return '';const p=a.pressure,hint=p?.firstKO?.actor==='a3'?'지원가가 먼저 쓰러졌습니다. 해당 교전 연습에서 지원가 근처 보호·도발·회복과 집중 공격을 비교하세요.':p?'해당 교전의 시작 HP와 덱을 확인하고, 연습에서 카드 또는 배치를 하나씩 바꿔 비교하세요.':'교전 기록에서 큰 순 체력 감소는 없었습니다. 다른 경로·보상 선택도 비교할 수 있습니다.';return `<section class="panel expedition-review"><h2>원정 준비와 체력 흐름</h2><div class="expedition-review-summary"><p><small>확인할 전투</small><strong>${p?esc(p.name):'큰 순 소모 없음'}</strong></p><p><small>교전 사이 순 회복</small><strong>${num(a.recovered)} HP</strong></p><p><small>후속 전투에서 사용한 변경 카드</small><strong>${a.changesKnown?a.usedNew.length+'종':'일부 미기록'}</strong></p></div><p class="note">${esc(hint)}</p>${p?`<button data-action="practice-open" data-origin="report" data-result="${p.index}">이 전투의 준비 다시 비교</button>`:''}<details data-inline><summary>방별 체력·덱 변화</summary><div class="expedition-review-table"><table><thead><tr><th>전투</th><th>시작 → 종료 HP</th><th>사이 회복 / 덱 변화</th></tr></thead><tbody>${a.fights.map(r=>`<tr><th>${r.room??'?'}방 · ${esc(r.name)}</th><td>${num(r.start)} → ${num(r.end)}<small>전투 순 변화 ${r.net==null?'미기록':(r.net>=0?'+':'')+num(r.net)}</small></td><td>${r.index?num(r.between)+' HP':'출발'}${r.revived?` · ${r.revived}명 복귀`:''}<small>${r.changed===null?'덱 미기록':r.changed.length?r.changed.map(c=>esc(D.cards[c.key].name)+(c.upgraded?' ✦':'')+' '+c.before+'→'+c.after).join(' / '):'덱 변경 없음'}</small></td></tr>`).join('')}</tbody></table></div>${a.boss?`<p>보스 진입 HP ${num(a.boss.start)} · 종료 ${num(a.boss.end)}</p>`:''}<p class="note">순 체력 변화는 피해와 전투 회복을 합친 값입니다. 사이 회복은 직전 종료와 다음 시작의 차이로, 개별 방의 회복량을 분리하지 않습니다. 마지막 전투 이후 휴식은 이 값에 포함되지 않습니다. 변경 카드 사용은 효과의 원인이나 강함을 증명하지 않습니다.</p></details></section>`;}
 function growthPanel(report){
  if(![1,2].includes(report.growthRulesVersion)||!window.ExpeditionGrowth)return '';
  const uses=window.ExpeditionGrowth.uses(report),ledger=report.recoveryLedger;
  const economy=ledger?`<p>전투 ${report.results.length}회 · 휴식 ${(report.routeChoices||[]).filter(x=>x.name===D.rooms.heal.name).length}회 · 카드 획득 ${(report.growthChoices||[]).filter(x=>x.kind==='card').length}장 · 진화 ${(report.growthChoices||[]).filter(x=>x.kind==='evolve').length}장 · 방 회복 ${num(ledger.reduce((n,x)=>n+x.gain,0))} HP · 복귀 ${ledger.reduce((n,x)=>n+x.revived,0)}명</p><details data-inline><summary>실제로 받은 방별 회복</summary>${ledger.map(x=>`<p>${x.depth+1}방 ${esc(x.label)} · +${num(x.gain)} HP${x.revived?' · '+x.revived+'명 복귀':''}</p>`).join('')||'<p>방 회복 없음</p>'}<p class="note">전투 중 회복은 제외합니다. 만전 체력에서 받은 정비는 0 HP로 기록됩니다.</p></details>`:'';
  return `<details class="panel growth-review" data-inline><summary>원정 성장 선택의 후속 사용 · ${uses.length}건</summary>${economy}<p class="note">그 사본을 편성한 후속 교전에서 같은 카드 종류의 사용 횟수를 집계합니다. 다른 사본도 포함하므로 획득·진화 사본 자체의 발동 횟수나 효과 증명이 아닙니다.</p>${uses.map(x=>`<p>${x.depth+1}방 ${x.kind==='evolve'?'진화':'획득'} · ${esc(D.cards[x.key].name)} · 후속 편성 ${x.equipped}전 · 같은 종류 사용 ${x.casts}회 ${x.used.length?`<button data-action="practice-open" data-origin="report" data-result="${x.used[0]}">사용 전투 다시 비교</button>`:'· 후속 사용 미확인'}</p>`).join('')||'<p>획득·진화한 카드가 없습니다.</p>'}${report.signatureMode==='guardDance'?'<p>진화 대신 수호 검무를 선택했습니다. 검무 피해는 줄고 실제 보호막 흡수가 궁극기 준비에 기여합니다.</p>':''}${(report.growthChoices||[]).some(x=>x.kind==='relay')?'<p>추격 릴레이를 선택했습니다. 각 전투의 전술 기록에서 발동과 명령 비용을 확인하세요.</p>':''}</details>`;
 }
 window.ExpeditionReview={analyze,panel,growthPanel};
})();
